import { chromium } from 'playwright'

const BASE = 'http://58.210.252.230:9002'
const USER = 'zsbase'
const PASS = 'ZS001Aa!'

const run = async () => {
  const browser = await chromium.launch({ headless: true })
  const ctx = await browser.newContext({ viewport: { width: 1600, height: 860 } })
  const page = await ctx.newPage()
  const apiLogs = []
  page.on('response', async (resp) => {
    const u = resp.url()
    if (u.includes('unionBank/page')) {
      try {
        const j = await resp.json()
        apiLogs.push({ url: u, keys: Object.keys(j), sample: JSON.stringify(j).slice(0, 600) })
      } catch (e) { apiLogs.push({ url: u, err: String(e) }) }
    }
  })

  try {
    await page.goto(`${BASE}/#/login`, { waitUntil: 'domcontentloaded', timeout: 30000 })
    await page.waitForSelector('.login-form', { timeout: 30000 })
    // account tab default? try fill username/password
    const userSel = page.locator('input[placeholder*="请输入用户名"], input[placeholder*="账号"], input[placeholder*="用户"]').first()
    await userSel.fill(USER).catch(()=>{})
    const pwdSel = page.locator('input[placeholder*="密码"]').first()
    await pwdSel.fill(PASS).catch(()=>{})
    await page.locator('.login-button').click({ force: true }).catch(()=>{})
    await page.waitForURL((url)=> !url.hash.includes('/login'), { timeout: 30000 })
    console.log('LOGIN OK, url=', page.url())

    // Navigate to account open add
    await page.goto(`${BASE}/#/spfzjjg/zjjg/ACCOUNT_OPEN/account/add`, { waitUntil: 'domcontentloaded', timeout: 30000 })
    await page.waitForTimeout(3000)
    console.log('PAGE url=', page.url())
    const bodyText = await page.locator('body').innerText().catch(()=> '')
    console.log('BODY HEAD:', bodyText.slice(0, 300).replace(/\n/g,' | '))

    // find 开户网点 input and click
    const openbankInput = page.locator('input[placeholder*="开户网点"]').first()
    const cnt = await openbankInput.count()
    console.log('openbankInput count=', cnt)
    if (cnt) {
      await openbankInput.click({ force: true })
      await page.waitForTimeout(2500)
      const dlg = page.locator('.zs-select-dialog').last()
      const pag = dlg.locator('.pagination-container')
      const pagCnt = await pag.count()
      const pagVisible = pagCnt ? await pag.first().isVisible() : false
      const pagText = pagCnt ? await pag.first().innerText().catch(()=> '') : ''
      console.log('PAGINATION count=', pagCnt, 'visible=', pagVisible, 'text=', pagText.replace(/\n/g,' '))
      // dialog box height / scroll
      const info = await dlg.evaluate((el) => {
        const body = el.querySelector('.el-dialog__body')
        const box = el.querySelector('.dialog-box')
        const wrap = el.querySelector('.select-dialog-table-wrap')
        const r = (e)=> e? {sh:e.scrollHeight, ch:e.clientHeight, oy:getComputedStyle(e).overflowY} : null
        return { body: r(body), box: r(box), wrap: r(wrap), hasPagination: !!el.querySelector('.pagination-container') }
      })
      console.log('DLG INFO=', JSON.stringify(info))
      await page.screenshot({ path: 'D:\\repository\\苏州市房地产监测V3\\inspect6084.png' })
    }
    console.log('API LOGS=', JSON.stringify(apiLogs, null, 2))
  } catch (e) {
    console.log('ERROR:', e.message)
    await page.screenshot({ path: 'D:\\repository\\苏州市房地产监测V3\\inspect6084_err.png' }).catch(()=>{})
  } finally {
    await browser.close()
  }
}
run()

