  const ctx = await browser.newContext({ viewport: { width: 1600, height: 860 }, storageState: storage })
  const page = await ctx.newPage()
  await page.goto(`${BASE}/#/spfzjjg/zjjg/ACCOUNT_OPEN/account/add`, { waitUntil: 'domcontentloaded', timeout: 30000 })
  await page.waitForTimeout(3000)
  // check logged in
  if (page.url().includes('/login')) { console.log('NOT LOGGED IN (storage expired)'); await browser.close(); return }

  await page.evaluate(() => {
    const f=(vm)=>{if(!vm)return null;if(vm.showVisionOfBank)return vm;for(const c of vm.$children||[]){const r=f(c);if(r)return r}return null};
    const vm=f(document.querySelector('#app')?.__vue__);
    if(vm){ vm.form.bankId = vm.form.bankId || '1'; vm.form.bankName='测试'; vm.showVisionOfBank() }
  })
  await page.waitForTimeout(4000)
  const dlg = page.locator('.zs-select-dialog').last()
  if (!(await dlg.count())) { console.log('NO DIALOG'); await browser.close(); return }

  const before = await dlg.evaluate(el => {
    const b=el.querySelector('.el-dialog__body'); const p=el.querySelector('.pagination-container')
    return { bodySh:b.scrollHeight, bodyCh:b.clientHeight, pagVisible: p? (p.getBoundingClientRect().bottom <= b.getBoundingClientRect().bottom + 1 && p.getBoundingClientRect().top>=b.getBoundingClientRect().top) : false }
  })
  console.log('BEFORE=', JSON.stringify(before))
  await page.screenshot({ path: `${OUT}\\verify_before.png` })

  // simulate fix: add table-scroll class + set table height
  await page.evaluate(() => {
    const el = document.querySelectorAll('.zs-select-dialog')
    const dlg = el[el.length-1]
    // find wrapper with class zs-select-dialog (could be same el)
    let wrapper = dlg
    dlg.classList.add('zs-select-dialog--table-scroll')
    // elementor: ensure el-dialog is direct child
    const table = dlg.querySelector('.el-table')
    if (table) table.style.height = '100%'
  })
  await page.waitForTimeout(600)
  const after = await dlg.evaluate(el => {
    const b=el.querySelector('.el-dialog__body'); const p=el.querySelector('.pagination-container')
    const br=b.getBoundingClientRect(), pr=p.getBoundingClientRect()
    return { bodySh:b.scrollHeight, bodyCh:b.clientHeight, pagVisible: pr.bottom <= br.bottom + 2 && pr.top >= br.top - 2, pagText:(p.innerText||'').replace(/\n/g,' '), dialogH: el.getBoundingClientRect().height }
  })
  console.log('AFTER=', JSON.stringify(after))
  await page.screenshot({ path: `${OUT}\\verify_after.png` })
  await browser.close()
}
run().catch(e=>{console.log('ERR',e.message);process.exit(1)})
